    sources:[{href:"https://www.nasa.gov/wp-content/uploads/2021/04/88796main_yf-12.pdf",label:"NASA — Mach 3+ YF-12 flight research"},{href:"https://www.nasa.gov/aeronautics/x-15/",label:"NASA — X-15 hypersonic research aircraft"}],
